llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C53"],
      "claim": "In healthy volunteers, the closest analogue ivabradine (compound 1) had an absolute oral bioavailability of 51.5 ± 17.8% (range 29–80%) after a 7.5 mg oral solution versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Ivabradine, which shares the dimethoxy-benzolactam and propylamine tertiary amine scaffold with the query, has an oral bioavailability close to 40% in healthy volunteers despite near-complete absorption and hepatic first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "A second estimate in the same ivabradine study gave an absolute bioavailability of 45.0 ± 17.0% (range 30–70%), again above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine, a less similar analogue, has a mean oral bioavailability of 4.9 ± 3.2% in patients, far below 20%, indicating extensive first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant, sharing dimethoxyphenyl/amide and basic amine features, had an absolute oral bioavailability of 11.2% in healthy subjects, below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Donepezil, a dimethoxybenzene-containing basic amine drug, has an oral bioavailability of about 99% in humans, demonstrating that this class can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Valbenazine, a tetrabenazine analogue, has an absolute oral bioavailability of approximately 49% in humans, showing that structural modification can raise F above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Carmegliptin, a dimethoxy-tetrahydroisoquinoline analogue, had an oral bioavailability of 30% in rats, above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Armepavine, a dimethoxy-tetrahydroisoquinoline, had an oral bioavailability of 11.3% in mice, below 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-similarity new evidence (ivabradine, Morgan 0.6441) shows absolute oral bioavailability of ~40–51% in healthy volunteers, well above the 20% threshold. Although less similar tetrabenazine and almorexant show low F, the close structural match to ivabradine and supporting high-F analogues (donepezil, valbenazine, carmegliptin) outweigh them. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "Ivabradine is the closest analogue but differs in lactam ring size (benzazepinone vs dihydroisoquinolinone) and the right-side bicyclic system (dimethoxyphenethyl vs tetralin-methylamine).",
    "Tetrabenazine low-F data come from a less similar scaffold and may not transfer to the query's lactam/tertiary amine system.",
    "One tetrabenazine record (C47) reporting ≥75% bioavailability is inconsistent with multiple direct measurements and is considered unreliable.",
    "Carmegliptin and armepavine data are from non-human species with variable results."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C53", "C48", "C46"],
      "decision_effect": "changed",
      "direction": "supportive",
      "family": "ivabradine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C56", "C51", "C55", "C47", "C52"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "tetrabenazine"
    },
    {
      "applicability": "low",
      "card_ids": ["C49", "C50"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "armepavine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C54", "C45"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "carmegliptin"
    }
  ],
  "revision_action": "flip"
}

